{"path":"about.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fcfbf9;--muted:#6b6b6b;--accent:#6b8e7f;--card:#ffffff;--glass:rgba(255,255,255,0.6);--mono:#222}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:var(--mono);background:linear-gradient(180deg,#fbfbfa 0%,#f6f7f5 40%),url('assets/img/pattern.svg');background-size:600px}
    header{display:flex;justify-content:space-between;align-items:center;padding:24px 32px}
    nav a{color:var(--muted);text-decoration:none;margin:0 12px;font-size:14px}
    .hero{max-width:900px;margin:28px auto;padding:36px;border-radius:14px;background:linear-gradient(180deg,rgba(255,255,255,0.85),rgba(250,250,250,0.85));box-shadow:0 6px 30px rgba(20,20,20,0.04)}
    .hero h1{margin:0 0 8px;font-weight:700;letter-spacing:-0.02em}
    .hero p.lead{margin:0;color:var(--muted);line-height:1.5}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:20px;margin-top:22px}
    .card{background:var(--card);padding:18px;border-radius:10px;box-shadow:0 6px 18px rgba(12,12,12,0.04)}
    .small{font-size:13px;color:var(--muted)}
    button.primary{background:var(--accent);color:white;border:0;padding:10px 14px;border-radius:8px;cursor:pointer}
    .planner label{display:block;margin:10px 0 6px;font-weight:600;font-size:13px}
    .planner input,.planner textarea,.planner select{width:100%;padding:8px;border-radius:8px;border:1px solid #e6e6e6}
    .summary{white-space:pre-wrap;background:#f7f7f7;padding:12px;border-radius:8px;font-family:monospace;font-size:13px}
    .wizard .step{display:none}
    .wizard .step.active{display:block}
    .metaphor{font-style:italic;color:var(--muted);margin-top:8px}
    footer{max-width:900px;margin:32px auto;padding:18px;color:var(--muted);font-size:13px}
    @media(max-width:880px){.grid{grid-template-columns:1fr;}.hero{margin:12px}}
  </style>
</head>
<body>
  <header>
    <div><a href='index.html' style='font-weight:700;color:var(--mono);text-decoration:none'>Home</a></div>
    <nav>
      <a href='about.html'>The Clinician</a>
      <a href='specialties.html'>What I Help With</a>
      <a href='approach.html'>How I Work</a>
      <a href='fees.html'>Investment</a>
      <a href='contact.html'>Reach Out</a>
    </nav>
  </header>

  <main class='hero' role='main'>
    <h1>About the practice</h1>
    <p class='lead'>Clinical practice rooted in clear boundaries, steady attention, and small changes that add up. I work with adults navigating transitions, sustained low mood, anxiety, and relationships. Sessions are practical, reflective, and anchored in your life.</p>

    <div class='grid'>
      <section>
        <div class='card'>
          <h3>My orientation</h3>
          <p class='small'>I draw from evidence-informed approaches—brief cognitive techniques, relational work, and skill-building. The work is collaborative: we name priorities, try small experiments, and refine what’s useful. I bring clinical training, clear confidentiality practices, and a focus on functional changes you can notice week to week.</p>
          <p class='metaphor'>Think of our work as building a clearer path through a familiar landscape—the map changes as we walk.</p>
        </div>

        <div class='card' style='margin-top:16px'>
          <h3>About me</h3>
          <p class='small'>I am a licensed clinician offering individual therapy via secure telehealth and select in-person hours. I prioritize safety, informed consent, and transparent boundaries about scope of care. I do not provide emergency services; if you are in crisis, call local emergency services or a crisis line.</p>
        </div>

        <div class='card' style='margin-top:16px'>
          <h3>Confidentiality & scope</h3>
          <p class='small'>What you share is protected within the limits of the law. I will outline limits to confidentiality, informed consent, and coordination with other providers as needed. This practice does not provide legal or medical emergency services.</p>
        </div>
      </section>

      <aside>
        <div class='card planner' aria-labelledby='planner-heading'>
          <h4 id='planner-heading'>Session Planner</h4>
          <p class='small'>Quickly sketch a plan to bring to our first conversation. Save or copy a plain-text summary.</p>
          <label>Primary goal</label>
          <input id='goal' placeholder='What matters most to you now?'>
          <label>Preferred rhythm</label>
          <select id='frequency'>
            <option>Weekly</option>
            <option>Biweekly</option>
            <option>Every three weeks</option>
            <option>Short series (4–6 sessions)</option>
          </select>
          <label>Session length</label>
          <select id='length'>
            <option>50 minutes</option>
            <option>75 minutes</option>
          </select>
          <label>Timeframe</label>
          <input id='timeframe' placeholder='e.g., 3 months, ongoing, short-term work'>
          <label>Top 3 priorities</label>
          <input id='p1' placeholder='1'>
          <input id='p2' placeholder='2' style='margin-top:8px'>
          <input id='p3' placeholder='3' style='margin-top:8px'>
          <div style='display:flex;gap:8px;margin-top:12px'>
            <button class='primary' id='buildPlan'>Build summary</button>
            <button id='clearPlan' style='border:1px solid #ddd;padding:10px;border-radius:8px;background:white;cursor:pointer'>Clear</button>
          </div>
          <div style='margin-top:12px'>
            <div class='summary' id='planSummary' aria-live='polite'>Your plan will appear here.</div>
            <div style='display:flex;gap:8px;margin-top:8px'>
              <button id='copyPlan' style='padding:8px;border-radius:8px;border:0;background:#2b7a5f;color:white;cursor:pointer'>Copy summary</button>
              <a class='small' href='book.html' style='display:inline-flex;align-items:center;gap:6px;color:var(--muted);text-decoration:none'>Start scheduling →</a>
            </div>
          </div>
        </div>

        <div class='card wizard' style='margin-top:16px'>
          <h4>Intake questions (self-screening)</h4>
          <p class='small'>A short, non-diagnostic set of prompts to help you notice what to bring to a first session.</p>
          <div id='wizardSteps'>
            <div class='step active' data-step='1'>
              <label>Which area is most active for you now?</label>
              <select id='area'>
                <option>Low mood / sadness</option>
                <option>Anxiety or worry</option>
                <option>Relationship stress</option>
                <option>Life transition</option>
                <option>Other</option>
              </select>
              <div style='margin-top:12px'><button class='primary' data-action='next'>Next</button></div>
            </div>
            <div class='step' data-step='2'>
              <label>When did this start or become noticeable?</label>
              <input id='onset' placeholder='A few weeks, months, years, after an event'>
              <div style='display:flex;gap:8px;margin-top:12px'>
                <button data-action='back' style='padding:8px;border-radius:8px;border:0;background:#eee;cursor:pointer'>Back</button>
                <button class='primary' data-action='next'>Next</button>
              </div>
            </div>
            <div class='step' data-step='3'>
              <label>What helps even a little?</label>
              <input id='helps' placeholder='Small activities, routines, people, settings'>
              <div style='display:flex;gap:8px;margin-top:12px'>
                <button data-action='back' style='padding:8px;border-radius:8px;border:0;background:#eee;cursor:pointer'>Back</button>
                <button class='primary' id='generateQs'>Generate questions</button>
              </div>
            </div>
          </div>

          <div style='margin-top:12px'>
            <div class='summary' id='questionsOutput'>A set of conversation prompts will appear here.</div>
            <div style='display:flex;gap:8px;margin-top:8px'>
              <button id='copyQs' style='padding:8px;border-radius:8px;border:0;background:#2b7a5f;color:white;cursor:pointer'>Copy questions</button>
              <a href='contact.html' class='small' style='color:var(--muted);text-decoration:none'>Ask a question by email</a>
            </div>
          </div>
        </div>
      </aside>
    </div>

    <div style='margin-top:18px;display:flex;gap:12px;align-items:center'>
      <a href='book.html' class='primary' style='text-decoration:none;padding:12px 16px;border-radius:10px'>{{PRIMARY_CTA_LABEL}}</a>
      <a href='contact.html' style='color:var(--muted);text-decoration:none'>Send a note</a>
    </div>
  </main>

  <footer>
    <div>{{BUSINESS_NAME}} — {{CITY}}, {{STATE}} • <a href='tel:{{PHONE}}' style='color:inherit;text-decoration:none'>{{PHONE}}</a> • <a href='mailto:{{EMAIL}}' style='color:inherit;text-decoration:none'>{{EMAIL}}</a></div>
    <p style='margin-top:10px'>Confidentiality: clinical notes and communications are protected within legal limits. Scope: this practice does not provide emergency care or forensic evaluations. If you are in immediate danger or have urgent medical needs, please call local emergency services or a crisis line.</p>
  </footer>

  <script>
    // Session Planner
    function buildPlan(){
      const goal = document.getElementById('goal').value.trim() || 'No primary goal entered.';
      const freq = document.getElementById('frequency').value;
      const length = document.getElementById('length').value;
      const timeframe = document.getElementById('timeframe').value || 'unspecified';
      const p1 = document.getElementById('p1').value.trim();
      const p2 = document.getElementById('p2').value.trim();
      const p3 = document.getElementById('p3').value.trim();
      let priorities = [p1,p2,p3].filter(Boolean).join('\n- ') || 'None listed';
      if(priorities !== 'None listed') priorities = '- ' + priorities;
      const text = ['Session Planner','------------','Primary goal: ' + goal,'Preferred rhythm: ' + freq,'Session length: ' + length,'Timeframe: ' + timeframe,'Priorities:','' + priorities].join('\n');
      document.getElementById('planSummary').textContent = text;
    }
    document.getElementById('buildPlan').addEventListener('click', buildPlan);
    document.getElementById('clearPlan').addEventListener('click', ()=>{
      ['goal','timeframe','p1','p2','p3'].forEach(id=>document.getElementById(id).value='');
      document.getElementById('planSummary').textContent = 'Your plan will appear here.';
    });
    document.getElementById('copyPlan').addEventListener('click', async ()=>{
      const txt = document.getElementById('planSummary').textContent;
      try{await navigator.clipboard.writeText(txt);document.getElementById('copyPlan').textContent='Copied';setTimeout(()=>document.getElementById('copyPlan').textContent='Copy summary',1500)}catch(e){alert('Copy failed — select and copy manually.')}
    });

    // Intake Wizard
    (function(){
      const steps = Array.from(document.querySelectorAll('.wizard .step'));
      let idx = 0;
      function show(i){steps.forEach((s,si)=>s.classList.toggle('active',si===i));idx=i}
      document.querySelectorAll('[data-action]').forEach(btn=>{
        btn.addEventListener('click',e=>{
          const act = e.currentTarget.getAttribute('data-action');
          if(act==='next' && idx < steps.length-1) show(idx+1);
          if(act==='back' && idx > 0) show(idx-1);
        });
      });
      document.getElementById('generateQs').addEventListener('click', ()=>{
        const area = document.getElementById('area').value;
        const onset = document.getElementById('onset').value || 'not specified';
        const helps = document.getElementById('helps').value || 'noted';
        const questions = [
          'Concise intake prompts',
          '-----------------------',
          '1) What is the change you most want to see in the next 2–3 months?\n',
          '2) When did you first notice this, and how has it changed since? (\n' + onset + ')',
          '3) Which situations or people make this better or worse?\n',
          '4) What small steps have helped, even briefly? (\n' + helps + ')',
          '5) What are your hopes and limits for therapy (time, focus, privacy)?\n',
          '6) Are there current safety concerns or urgent needs we should address at the first session?\n',
          '\nSuggested focus based on your selection: ' + area
        ].join('\n');
        document.getElementById('questionsOutput').textContent = questions;
      });
      document.getElementById('copyQs').addEventListener('click', async ()=>{
        const t = document.getElementById('questionsOutput').textContent;
        try{await navigator.clipboard.writeText(t);document.getElementById('copyQs').textContent='Copied';setTimeout(()=>document.getElementById('copyQs').textContent='Copy questions',1500)}catch(e){alert('Copy failed — select and copy manually.')}
      });
    })();
  </script>
</body>
</html>"} 
