<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>What I Help With — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffdfb;--accent:#7a6b9f;--muted:#6c6c6c;--card:#fff;--mono:#111}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;background:linear-gradient(0deg,#fffdfb, #f5f7fb);color:var(--mono);background-image:url('assets/img/pattern.svg');background-size:500px}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px 28px}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none;font-size:14px}
    .wrap{max-width:1100px;margin:24px auto;padding:0 20px}
